c:
.btn {
  background-color: blue;
  transition: background-color 0.4s;
}
.btn:hover {
  background-color: green;
}

.card {
  transition: opacity 0.2s, transform 0.6s;
}

.loader {
  animation-name: spin;
  animation-duration: 2s;
  animation-iteration-count: 3;
}

.spinner {
  animation: spin 3s linear infinite;
}
.spinner:hover {
  animation-play-state: paused;
}

.clock-hand {
  animation: rotateHand 60s steps(60) infinite;
}

.card {
  animation: fadeIn 1s ease, slideUp 1s ease;
}

.modal {
  transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

.card:nth-child(1) { animation-delay: 0s; }
.card:nth-child(2) { animation-delay: 0.15s; }
.card:nth-child(3) { animation-delay: 0.3s; }

.menu {
  opacity: 0;
  transition: opacity 0.3s 0.2s;
}
.menu:hover {
  opacity: 1;
  transition: opacity 0.3s 0s;
}

@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.2); }
  75% { transform: scale(1); }
  100% { transform: scale(1); }
}

.character {
  width: 64px; height: 64px;
  background: url('spritesheet.png') 0 0;
  animation: walk 0.8s steps(8) infinite;
}
@keyframes walk {
  to { background-position: -512px 0; }
}

.badge {
  animation: popIn 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes popIn {
  0% { transform: scale(0); }
  100% { transform: scale(1); }
}

.box {
  animation: move 2s ease;
}
@keyframes move {
  0% { left: 0; animation-timing-function: linear; }
  50% { left: 100px; }
  100% { left: 200px; }
}

.door {
  transform-origin: left center;
  transition: transform 0.6s ease;
}
.door:hover {
  transform: perspective(600px) rotateY(-60deg);
}

.card {
  rotate: 5deg;
  transition: scale 0.3s ease;
}
.card:hover {
  scale: 1.1;
}

.banner {
  opacity: 1;
  animation: fadeIn 1s ease 2s backwards;
}
@keyframes fadeIn {
  0% { opacity: 0; }
  100% { opacity: 1; }
}

@property --angle {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}
.dial {
  transition: --angle 0.5s ease;
}

.card::after {
  content: ''; position: absolute; inset: 0;
  box-shadow: 0 10px 30px rgba(0,0,0,0.3);
  opacity: 0;
  transition: opacity 0.3s ease;
}
.card:hover::after {
  opacity: 1;
}

dialog[open] {
  opacity: 1;
  transform: scale(1);
  transition: opacity 0.3s, transform 0.3s;
  @starting-style {
    opacity: 0;
    transform: scale(0.9);
  }
}

.spinner {
  animation: rotate 2s ease 1s 3 normal forwards;
}

@keyframes bounce {
  to { transform: translateY(-50px); }
}
@media (max-width: 600px) {
  @keyframes bounce {
    to { transform: translateY(-20px); }
  }
}

.tooltip {
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, visibility 0s 0.3s;
}
.tooltip.active {
  opacity: 1;
  visibility: visible;
  transition: opacity 0.3s ease, visibility 0s 0s;
}

.checkmark {
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  animation: draw 1s ease forwards;
}
@keyframes draw {
  to { stroke-dashoffset: 0; }
}

.card-inner {
  transform-style: preserve-3d;
  transition: transform 0.6s;
}
.card:hover .card-inner {
  transform: rotateY(180deg);
}

@keyframes morph {
  0% { clip-path: circle(0% at 50% 50%); }
  100% { clip-path: circle(100% at 50% 50%); }
}

.item {
  animation: slideUp 0.4s ease both;
  animation-delay: calc(var(--i) * 80ms);
}

.card {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(0px);
  transition: backdrop-filter 0.4s ease;
}
.card:hover {
  backdrop-filter: blur(16px);
}

@keyframes neonGlow {
  from { text-shadow: 0 0 5px #ff00de, 0 0 10px #ff00de; }
  to { text-shadow: 0 0 20px #ff00de, 0 0 30px #ff00de; }
}
.sign {
  animation: neonGlow 1.5s ease-in-out infinite alternate;
}

.modal {
  z-index: 10;
  opacity: 1;
  transition: opacity 0.3s, z-index 0s 0s;
}
.modal.closed {
  z-index: -1;
  opacity: 0;
  transition: opacity 0.3s, z-index 0s 0.3s;
}

.btn {
  transform: translateY(-20px);
  animation: wobble 1s infinite;
  animation-composition: add;
}
@keyframes wobble {
  0%, 100% { transform: rotate(0deg); }
  50% { transform: rotate(10deg); }
}

.accordion-content {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.3s ease-out;
}
.accordion-content.expanded {
  grid-template-rows: 1fr;
}

.nav-item {
  opacity: 0;
  transform: translateY(20px);
  animation: enter 0.4s ease forwards;
}
.nav-item:nth-child(1) { animation-delay: 0.1s; }
.nav-item:nth-child(2) { animation-delay: 0.2s; }
.nav-item:nth-child(3) { animation-delay: 0.3s; }

.progress-bar {
  scale: 0 1;
  transform-origin: left;
  animation: grow linear;
  animation-timeline: scroll();
}
@keyframes grow {
  to { scale: 1 1; }
}

.photo {
  animation: reveal linear both;
  animation-timeline: view();
  animation-range: entry 0% entry 100%;
}
@keyframes reveal {
  from { opacity: 0; scale: 0.8; }
  to { opacity: 1; scale: 1; }
}

.badge {
  animation-name: spin, fade;
  animation-duration: 2s, 1s;
  animation-iteration-count: infinite, 1;
}

.rocket {
  offset-path: path('M 0 100 Q 150 0 300 100');
  animation: fly 3s linear infinite;
}
@keyframes fly {
  to { offset-distance: 100%; }
}

.blob {
  border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%;
  transition: border-radius 1s ease-in-out;
}
.blob:hover {
  border-radius: 30% 60% 70% 40% / 50% 60% 30% 60%;
}

.tag {
  background-color: red;
  transition: background-color 1s step-start;
}
.tag:hover {
  background-color: green;
}

.box {
  animation-iteration-count: infinite;
  animation: pulse 2s ease;
}

.bar {
  animation: wave 1s ease-in-out infinite alternate;
  animation-delay: calc(var(--index) * -0.15s);
}
@keyframes wave {
  from { transform: scaleY(0.2); }
  to { transform: scaleY(1); }
}

.icon-path {
  d: path('M 10 10 H 90 V 90 H 10 Z');
  transition: d 0.4s ease;
}
.icon:hover .icon-path {
  d: path('M 20 20 H 80 V 80 H 20 Z');
}

@property --gradient-angle {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}
.card {
  background: conic-gradient(from var(--gradient-angle), red, blue, red);
  animation: spinAngle 3s linear infinite;
}
@keyframes spinAngle {
  to { --gradient-angle: 360deg; }
}

.card {
  animation: zoom linear both;
  animation-timeline: view();
  animation-range: contain 0% contain 100%;
}
@keyframes zoom {
  from { scale: 0.8; }
  to { scale: 1.2; }
}

.layout {
  display: grid;
  grid-template-columns: 250px 1fr;
  transition: grid-template-columns 0.4s ease;
}
.layout.collapsed {
  grid-template-columns: 60px 1fr;
}

.banner {
  mask-image: linear-gradient(to right, black 50%, transparent 50%);
  mask-size: 200% 100%;
  mask-position: 100% 0;
  transition: mask-position 0.5s ease;
}
.banner:hover {
  mask-position: 0 0;
}

.ball {
  animation: drop 1s linear(0, 1 50%, 0.7 65%, 1 78%, 0.9 88%, 1);
}

.modal {
  display: none;
  opacity: 0;
  transition: display 0.3s allow-discrete, opacity 0.3s;
}
.modal.open {
  display: block;
  opacity: 1;
  @starting-style {
    opacity: 0;
  }
}

:root {
  interpolate-size: allow-keywords;
}
.panel {
  height: 0;
  overflow: hidden;
  transition: height 0.4s ease;
}
.panel.open {
  height: auto;
}

.scene {
  perspective: 800px;
  perspective-origin: 50% 50%;
}
.cube {
  transform-style: preserve-3d;
}

.carousel {
  scroll-timeline: --carouselTimeline inline;
}
.indicator {
  animation: fillProgress linear both;
  animation-timeline: --carouselTimeline;
}

.btn {
  position: relative;
  overflow: hidden;
}
.btn::before {
  content: ''; position: absolute; inset: 0;
  background: gold;
  transform: translateX(-100%);
  transition: transform 0.3s ease-out;
}
.btn:hover::before {
  transform: translateX(0);
}

.box {
  animation: slide 1s ease 2 alternate forwards;
}
@keyframes slide {
  from { transform: translateX(0); }
  to { transform: translateX(200px); }
}

.hero {
  view-timeline-name: --heroTimeline;
}
.header-indicator {
  animation: fade linear both;
  animation-timeline: --heroTimeline;
}

.heading {
  font-family: 'Inter Variable', sans-serif;
  font-weight: 300;
  transition: font-weight 0.3s ease;
}
.heading:hover {
  font-weight: 700;
}

const dx = first.left - last.left;
const dy = first.top - last.top;
el.style.transform = `translate(${dx}px, ${dy}px)`;

const anim = el.animate(
  [{ transform: 'scale(1)' }, { transform: 'scale(1.2)' }],
  { duration: 300, fill: 'forwards' }
);
await anim.finished;
el.remove();

const timeline = new ScrollTimeline({
  source: document.documentElement,
  axis: 'block'
});
el.animate(
  { transform: ['scaleX(0)', 'scaleX(1)'] },
  { timeline }
);

.popover {
  transition: opacity 0.3s, transform 0.3s, overlay 0.3s allow-discrete, display 0.3s allow-discrete;
  opacity: 0;
  transform: scale(0.9);
}
.popover:popover-open {
  opacity: 1;
  transform: scale(1);
  @starting-style {
    opacity: 0;
    transform: scale(0.9);
  }
}

.satellite {
  offset-path: circle(150px at 50% 50%);
  animation: orbit 4s linear infinite;
}
@keyframes orbit {
  to { offset-distance: 100%; }
}

@container (min-width: 500px) {
  .card {
    animation: slideInWide 0.5s ease-out;
  }
}

